package errs

import (
	"errors"
	"fmt"
)

// PROBLEM
//
// LoadBefore wraps errors with %v. That keeps the text but throws away the
// error itself. The caller can no longer ask "was this ErrNotFound?" with
// errors.Is, or "was this a ValidationError, and which field?" with
// errors.As. All that is left is searching the message text, which breaks the
// day someone rewords it.
//
// TRY IT
//
// Read the two TestBefore_* tests in errs_test.go. In both, the message says
// exactly what went wrong, and errors.Is / errors.As still answer no.
//
// Do not edit this file. Your work goes in after.go.

// ErrNotFound is a sentinel: a known condition that carries no data.
var ErrNotFound = errors.New("not found")

// ValidationError is a typed error: it carries data the caller may want.
type ValidationError struct {
	Field  string
	Reason string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("invalid %s: %s", e.Field, e.Reason)
}

var orders = map[string]string{"42": "order 42"}

// LoadBefore returns the order text for id.
func LoadBefore(id string) (string, error) {
	if id == "" {
		return "", fmt.Errorf("load: %v", &ValidationError{Field: "id", Reason: "must not be empty"})
	}
	v, ok := orders[id]
	if !ok {
		return "", fmt.Errorf("load %q: %v", id, ErrNotFound)
	}
	return v, nil
}
